@namespace sv_a8b8243907104b86ab5b555676f4b529.Components.Pages.Settings

@if (Visible)
{
    <div class="dialog-overlay" @onclick="Cancel">
        <div class="dialog" @onclick:stopPropagation="true">
            <h3>Revoke Session</h3>
            <p>Are you sure you want to revoke the session on <strong>@DeviceName</strong>? This will sign out that device immediately.</p>
            <div class="dialog-actions">
                <button class="btn-danger" @onclick="Confirm">Revoke</button>
                <button class="btn-secondary" @onclick="Cancel">Cancel</button>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public bool Visible { get; set; }
    [Parameter] public string DeviceName { get; set; } = "";
    [Parameter] public EventCallback OnConfirm { get; set; }
    [Parameter] public EventCallback OnCancel { get; set; }

    private async Task Confirm() => await OnConfirm.InvokeAsync();
    private async Task Cancel() => await OnCancel.InvokeAsync();
}

