<div class="settings-section">
    <h2>Appearance</h2>

    @if (_loading)
    {
        <p class="loading">Loading appearance settings...</p>
    }
    else
    {
        <div class="appearance-form">
            <div class="form-group">
                <h3>Theme</h3>
                <div class="radio-group">
                    <label class="radio-item">
                        <input type="radio" name="theme" value="Light" checked="@(_theme == "Light")" @onchange="() => _theme = \"Light\"" />
                        <span>Light</span>
                    </label>
                    <label class="radio-item">
                        <input type="radio" name="theme" value="Dark" checked="@(_theme == "Dark")" @onchange="() => _theme = \"Dark\"" />
                        <span>Dark</span>
                    </label>
                    <label class="radio-item">
                        <input type="radio" name="theme" value="System" checked="@(_theme == "System")" @onchange="() => _theme = \"System\"" />
                        <span>System</span>
                    </label>
                </div>
            </div>

            <div class="form-group">
                <h3>Font Size</h3>
                <div class="radio-group">
                    <label class="radio-item">
                        <input type="radio" name="fontSize" value="Small" checked="@(_fontSize == "Small")" @onchange="() => _fontSize = \"Small\"" />
                        <span>Small</span>
                    </label>
                    <label class="radio-item">
                        <input type="radio" name="fontSize" value="Medium" checked="@(_fontSize == "Medium")" @onchange="() => _fontSize = \"Medium\"" />
                        <span>Medium</span>
                    </label>
                    <label class="radio-item">
                        <input type="radio" name="fontSize" value="Large" checked="@(_fontSize == "Large")" @onchange="() => _fontSize = \"Large\"" />
                        <span>Large</span>
                    </label>
                </div>
            </div>

            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" @bind="_language">
                    <option value="en">English</option>
                    <option value="es">Español</option>
                    <option value="fr">Français</option>
                    <option value="de">Deutsch</option>
                    <option value="ja">日本語</option>
                    <option value="zh">中文</option>
                </select>
            </div>

            <div class="form-group">
                <label class="toggle-item">
                    <input type="checkbox" @bind="_compactMode" />
                    <span class="toggle-label">Compact Mode</span>
                </label>
            </div>

            <div class="live-preview" style="@GetPreviewStyle()">
                <h4>Live Preview</h4>
                <p>This is how your content will look with the selected settings.</p>
                <p>The quick brown fox jumps over the lazy dog.</p>
            </div>

            <div class="form-actions">
                <button class="btn-primary" @onclick="SaveAsync" disabled="@_saving">
                    @(_saving ? "Saving..." : "Save")
                </button>
            </div>

            @if (_successMessage is not null)
            {
                <div class="toast success">@_successMessage</div>
            }
        </div>
    }
</div>

@code {
    private bool _loading = true;
    private bool _saving;
    private string? _successMessage;

    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewStyle()
    {
        var bg = _theme switch
        {
            "Dark" => "background-color: #1e1e2e; color: #cdd6f4;",
            "Light" => "background-color: #ffffff; color: #1e1e2e;",
            _ => "background-color: #f5f5f5; color: #333;"
        };

        var size = _fontSize switch
        {
            "Small" => "font-size: 0.85rem;",
            "Large" => "font-size: 1.2rem;",
            _ => "font-size: 1rem;"
        };

        var padding = _compactMode ? "padding: 0.5rem;" : "padding: 1rem;";

        return $"{bg} {size} {padding} border-radius: 8px; border: 1px solid #ddd; margin-top: 1rem;";
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _successMessage = null;
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _saving = false;
        _successMessage = "Appearance saved successfully!";
        _ = ClearMessageAfterDelay();
    }

    private async Task ClearMessageAfterDelay()
    {
        await Task.Delay(3000);
        _successMessage = null;
        await InvokeAsync(StateHasChanged);
    }
}

